 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    split = None
    for r in range(h):
        if len(set(grid[r])) == 1:
            split = ("row", r)
            break
    if split is None:
        for c in range(w):
            if len({grid[r][c] for r in range(h)}) == 1:
                split = ("col", c)
                break
    if split is None:
        raise ValueError("no uniform separator")

    orient, k = split
    if orient == "row":
        a, b = grid[:k], grid[k + 1:]
    else:
        a = [row[:k] for row in grid]
        b = [row[k + 1:] for row in grid]
    if len(a) != len(b) or any(len(x) != len(y) for x, y in zip(a, b)):
        raise ValueError("panels are not equally sized")

    bg_a = Counter(v for row in a for v in row).most_common(1)[0][0]
    bg_b = Counter(v for row in b for v in row).most_common(1)[0][0]
    return [[2 if a[r][c] != bg_a and b[r][c] != bg_b else 0
             for c in range(len(a[0]))] for r in range(len(a))]
"
}

